-- mod-classless-wildcard: elemental ability variants (GENERATED)
--
-- Do not hand-edit: regenerate with data/sql/generators/gen_elemental_variants.py.
--
-- Every physical strike in the pool dealt as an element instead: the same
-- swing, cost and cooldown, at a reduced weapon coefficient, with an elemental
-- add that scales with spell power and, where a slot allowed, one rider the
-- element is known for. The shape is Frost Strike's. Design and every id block
-- are in PLAN-elemental-variants.md.
--
-- The client patch appends the SAME rows to the player's Spell.dbc from
-- client-patch/elemental_manifest.json, written by the same run of the
-- generator, so what the server deals and what the tooltip shows agree.
--
-- This run: bases=Sinister Strike elements=fire ranks=first coefficient=85 spellpower=0.15

CREATE TABLE IF NOT EXISTS `cw_ability_variants` (
  `variant_first_spell` INT UNSIGNED NOT NULL COMMENT 'rank 1 of the variant line',
  `base_first_spell`    INT UNSIGNED NOT NULL COMMENT 'rank 1 of the ability it varies',
  `element`             TINYINT UNSIGNED NOT NULL COMMENT '1 fire 2 frost 3 earth 4 poison 5 arcane 6 shadow 7 holy',
  `enabled`             TINYINT UNSIGNED NOT NULL DEFAULT 1,
  PRIMARY KEY (`variant_first_spell`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Classless elemental ability variants';

DELETE FROM `spell_dbc` WHERE `ID` BETWEEN 950000 AND 957167;
DELETE FROM `skilllineability_dbc` WHERE `Spell` BETWEEN 950000 AND 957167;
DELETE FROM `spell_ranks` WHERE `first_spell_id` BETWEEN 950000 AND 957167;
DELETE FROM `cw_ability_variants` WHERE `variant_first_spell` BETWEEN 950000 AND 957167;

